{
  "name": "Innova 300C 系列离子激光器",
  "name_en": "Innova 300C Series Ion Laser",
  "manufacturer": "Coherent",
  "description": "Innova 300C 系列是一类实验室用连续波气体离子激光器，常见版本包括氩离子和氪离子型号，用于提供稳定的可见光激光输出。该设备常用于光学实验、光谱测试、荧光激发、光路对准以及其他需要连续激光源的科研场景，并支持通过电流、功率及腔内相关参数进行输出优化。",
  "description_en": "The Innova 300C Series is a laboratory continuous-wave gas ion laser family, with common versions including argon-ion and krypton-ion models, used to provide stable visible laser output. It is commonly used in optical experiments, spectroscopy, fluorescence excitation, beam alignment, and other research applications requiring a continuous laser source, with output optimization through current, power, and intracavity-related settings.",
  "tag_hints": [
    "ion laser",
    "argon ion laser",
    "krypton ion laser",
    "continuous-wave visible laser",
    "laser power regulation",
    "optical spectroscopy",
    "fluorescence excitation"
  ],
  "actions": [
    {
      "action_name": "auto-center_powertrack_async",
      "description": "异步将 PowerTrack 居中并关闭。",
      "description_en": "Asynchronously center PowerTrack and turn it off."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备通信与基本状态。",
      "description_en": "Initialize device communication and basic state."
    },
    {
      "action_name": "auto-query",
      "description": "发送查询命令并读取激光器响应。",
      "description_en": "Send a query command and read the laser response."
    },
    {
      "action_name": "auto-recalibrate_powertrack_async",
      "description": "异步重新校准 PowerTrack。",
      "description_en": "Asynchronously recalibrate PowerTrack."
    },
    {
      "action_name": "auto-baudrate",
      "description": "设置串行通信波特率。",
      "description_en": "Set the serial communication baud rate."
    },
    {
      "action_name": "auto-faults",
      "description": "获取当前所有活动故障列表。",
      "description_en": "Get the list of all active faults."
    },
    {
      "action_name": "auto-is_in_start_delay",
      "description": "获取设备是否处于启动延时状态。",
      "description_en": "Get whether the device is in start delay."
    },
    {
      "action_name": "auto-etalon_temperature_setpoint",
      "description": "获取或设置 etalon 温度设定值。",
      "description_en": "Get or set the etalon temperature setpoint."
    },
    {
      "action_name": "auto-magnetic_field_setpoint_high",
      "description": "获取或设置高磁场设定值。",
      "description_en": "Get or set the high magnetic field setpoint."
    },
    {
      "action_name": "auto-powertrack_position",
      "description": "获取或设置 PowerTrack 电磁线圈的相对位置。",
      "description_en": "Get or set the relative position of the PowerTrack solenoids."
    },
    {
      "action_name": "auto-recalibrate_powertrack",
      "description": "重新校准 PowerTrack。",
      "description_en": "Recalibrate PowerTrack."
    },
    {
      "action_name": "auto-center_powertrack",
      "description": "将 PowerTrack 居中并关闭。",
      "description_en": "Center PowerTrack and turn it off."
    },
    {
      "action_name": "auto-current_setpoint",
      "description": "获取或设置电流设定值。",
      "description_en": "Get or set the current setpoint."
    },
    {
      "action_name": "auto-power_setpoint",
      "description": "获取或设置功率设定值。",
      "description_en": "Get or set the power setpoint."
    }
  ]
}

